import { path } from '@servicenow/sdk-build-core'
import { Project } from '../../src'

describe('support for "if" directories', () => {
    test('places records into an if directory for ServiceNow scopes (e.g. sn_)', async () => {
        const project = new Project({ config: { scope: 'sn_app' } })

        const fluentFile = project.addFile({
            path: path.join('src', 'fluent', 'if', 'com.sn_other_app', 'acls.now.ts'),
            content: `
import { Acl } from '@servicenow/sdk/core'

Acl({
    $id: Now.ID['my-acl'],
    type: 'record',
    operation: 'read',
    table: 'sn_app_table',
    roles: ['sn_app.admin'],
})

`,
        })

        const diagnostics = (await fluentFile.getDiagnostics()).map((d) => d.message)
        expect(diagnostics).toEqual([])

        const files = (await fluentFile.getOutput()).map((f) => f.path)

        expect(files).toHaveLength(2)
        expect(files).toEqual([
            expect.stringContaining('dist/app/if/com.sn_other_app/update/sys_security_acl_'),
            expect.stringContaining('dist/app/if/com.sn_other_app/update/sys_security_acl_role_'),
        ])
    })

    test('can place "if" directory records into multiple package names', async () => {
        const project = new Project({ config: { scope: 'sn_app' } })

        const aclFile = project.addFile({
            path: path.join('src', 'fluent', 'if', 'com.sn_other_app', 'acls.now.ts'),
            content: `
import { Acl } from '@servicenow/sdk/core'

Acl({
    $id: Now.ID['my-acl'],
    type: 'record',
    operation: 'read',
    table: 'sn_app_table',
    roles: ['sn_app.admin'],
})

`,
        })

        const tableFile = project.addFile({
            path: path.join('src', 'fluent', 'if', 'com.sn_employee', 'tables.now.ts'),
            content: `
import { Table } from '@servicenow/sdk/core'

export const sn_my_table = Table({
    name: 'sn_my_table',
    schema: {},
})`,
        })

        expect((await aclFile.getDiagnostics()).map((d) => d.message)).toEqual([])
        expect((await tableFile.getDiagnostics()).map((d) => d.message)).toEqual([])

        const filePaths = (await project.getOutput()).map((f) => f.path)
        expect(filePaths).toEqual(
            expect.arrayContaining([
                expect.stringContaining('dist/app/if/com.sn_other_app/update/sys_security_acl_'),
                expect.stringContaining('dist/app/if/com.sn_other_app/update/sys_security_acl_role_'),
                expect.stringContaining('dist/app/if/com.sn_employee/dictionary/sn_my_table.xml'),
            ])
        )
    })

    test('does NOT place records into an if directory for non-ServiceNow scopes', async () => {
        const project = new Project() // default x_ scope

        const fluentFile = project.addFile({
            path: path.join('src', 'fluent', 'if', 'com.sn_other_app', 'acls.now.ts'),
            content: `
import { Acl } from '@servicenow/sdk/core'

Acl({
    $id: Now.ID['my-acl'],
    type: 'record',
    operation: 'read',
    table: 'sn_app_table',
    roles: ['sn_app.admin'],
})

`,
        })

        const diagnostics = (await fluentFile.getDiagnostics()).map((d) => d.message)
        expect(diagnostics).toEqual([])

        const files = (await fluentFile.getOutput()).map((f) => f.path)

        expect(files).toHaveLength(2)
        expect(files).toEqual([
            expect.stringContaining('dist/app/update/sys_security_acl_'),
            expect.stringContaining('dist/app/update/sys_security_acl_role_'),
        ])
    })
})
